// Rule-based pre-check: adds a NOTE for the agent when the message clearly needs a special action.
const msg = String($json.chatInput || '');
const m = msg.toLowerCase();
const notes = [];
if (/manager|human|real person|complain|worst|third time|angry|furious|ridiculous|fed up|cheat|fraud/.test(m))
  notes.push('The customer is upset or asks for a human: look up the order if an order ID is given, then you MUST call escalate_to_human and give the ticket ID.');
if (/refund/.test(m) && /ut\d{4}/.test(m))
  notes.push('Refund request: call order_lookup; if the order amount is more than Rs 5000 you MUST call escalate_to_human (you cannot approve it) and give the ticket ID.');
if (/\b(stock|in stock|available|availability|restock|reorder|purchase order|inventory|low stock)\b/.test(m) && !/stock market/.test(m))
  notes.push('This is about stock or purchase orders: call inventory_expert with the full question and pass its answer on. Do not guess availability.');
if (/return|exchange|does not fit|doesn't fit|too (small|big|tight|loose)|wrong size/.test(m) && /ut\d{4}/.test(m))
  notes.push('Return question about an order: call order_lookup for the order AND faq_knowledge for the return and refund policy, then answer with both (no stock check needed).');
if (/diwali|discount|coupon|promo|offer|sale|code|gift card|loyalty/.test(m) && !/python|javascript|script|program/.test(m))
  notes.push('Offers and coupon codes: call website_knowledge first and give ONLY codes that appear in its result. Never invent a code.');
if (/python|javascript|java |code|script|program|homework|essay|poem|recipe|weather|cricket|movie|stock market|bitcoin/.test(m)
    && !/order|ut\d{4}|return|refund|size|deliver|kurta|shirt|jeans|hoodie|in stock|restock|low stock/.test(m))
  notes.push('This is NOT about UrbanThread. Do not answer it and do not write code: reply that you can only help with UrbanThread orders, returns, sizes, delivery, offers and stock.');
// Flags for the 'guaranteed escalation' step after the agent.
const oid = (msg.toUpperCase().match(/UT\d{4}/) || [''])[0];
const phone = (msg.replace(/[\s-]/g, '').match(/(\+?91)?[6-9]\d{9}/) || [''])[0];
const name = (msg.match(/\b(?:i am|i'm|my name is|this is)\s+([A-Z][a-z]+)/) || ['', ''])[1];
const flags = { escalate: /manager|human|real person|complain|worst|third time|angry|furious|ridiculous|fed up|cheat|fraud/.test(m),
  refund: /refund/.test(m), order_id: oid, phone, name, original: msg };
return [{ json: { ...$json, intent: flags, chatInput: notes.length ? msg + '\n\n[NOTE FOR ASSISTANT: ' + notes.join(' ') + ']' : msg } }];

parameters.query:
SELECT order_id, customer_name, phone, amount_inr, items, status, expected_delivery::text AS expected_delivery, courier, tracking_no
FROM orders
WHERE order_id = UPPER(TRIM($1)) LIMIT 1;

parameters.jsCode:
// Decide if a human ticket is required but the agent did not create one.
const intent = $('Detect Intent (rules)').first().json.intent || {};
const order = $json.order_id ? $json : {};
let reply = String($('ShopAssist AI Agent').first().json.output || '').trim();
if (!reply) {  // the AI step failed (e.g. bad tool call): answer from the database / rules instead
  const r = order.order_id ? $('Order Details (for escalation check)').first().json : null;
  reply = r ? `Your order ${r.order_id} (${r.items}) is ${String(r.status).replace(/_/g, ' ')}. Expected delivery: ${String(r.expected_delivery).slice(0, 10)}, courier ${r.courier}, tracking ${r.tracking_no}.`
    : (intent.escalate || intent.refund) ? 'I am sorry for the trouble. Let me connect you with our support team.'
    : 'Sorry, I could not process that just now. Please share your order ID (like UT1003) or ask about returns, sizes, delivery, offers or stock.';
}
const bigRefund = intent.refund && Number(order.amount_inr || 0) > 5000;
const needs = (intent.escalate || bigRefund) && !/TKT-\d+/.test(reply);
const reason = intent.escalate ? 'Customer is upset or asked for a human' : 'Refund above Rs 5,000 needs human approval';
return [{ json: { needs_ticket: needs, reply,
  customer_name: intent.name || order.customer_name || 'Unknown',
  phone: intent.phone || order.phone || '',
  order_id: intent.order_id || '',
  reason,
  conversation_summary: (reason + '. Customer wrote: ' + String(intent.original || '')).slice(0, 1500) } }];
